package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaNlDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Bescherming tegen alle schade", "In de naam van Allah, met wiens naam niets op aarde of in de hemelen schade kan veroorzaken, en Hij is de Alhorende, de Alwetende.", "Drie keer per ochtend en avond.", "Wie het 's ochtends en 's avonds drie keer zegt, hem zal niets schaden."),
        "dua_raditu_billahi" to DuaText("Tevredenheid met Allah als Heer", "Ik ben tevreden met Allah als mijn Heer, met de Islam als mijn religie en met Mohammed ﷺ als mijn Profeet.", "Drie keer 's ochtends en 's avonds.", "Het wordt een recht voor Allah om hem te behagen op de Dag des Oordeels."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah is voldoende)", "Allah is voldoende voor mij; er is geen god dan Hij. Op Hem stel ik mijn vertrouwen, en Hij is de Heer van de Machtige Troon.", "Zeven keer 's ochtends en 's avonds.", "Een vers uit de Koran; Allah is voldoende tegen de zorgen van deze wereld en het Hiernamaals."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Glorie zij Allah en alle lof is aan Hem.", "Honderd keer per dag.", "Van wie het honderd keer per dag zegt, worden zijn zonden vergeven, ook al zijn ze als het schuim van de zee."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Aan Hem is de heerschappij en aan Hem is de lof, en Hij heeft macht over alle dingen.", "Het is een grote deugd om het honderd keer per dag te zeggen.", "De beloning voor het bevrijden van tien slaven, het schrijven van honderd goede daden, het uitwissen van honderd zonden en bescherming tegen Shaytan tot de avond."),
        "dua_leaving_mosque" to DuaText("Het verlaten van de moskee", "O Allah, ik vraag U om Uw milddadigheid.", "Bij het uitstappen uit de moskee met de linkervoet.", "Vragen om de gunst en voorziening van Allah bij het verlaten van de moskee."),
        "dua_after_adhan" to DuaText("Na de Adhan", "O Allah, Heer van deze volmaakte oproep en het gebed dat op het punt staat te worden verricht, schenk Mohammed ﷺ al-Wasilah en deugd, en verhef hem tot de Geprezen Plaats die U hem hebt beloofd.", "Nadat de adhan is voltooid.", "Iedereen die dit zegt, zal op de Dag des Oordeels de tussenkomst van de Profeet ﷺ krijgen."),
        "dua_after_salah_istighfar" to DuaText("Na Fard Salah", "Ik zoek Allah's vergiffenis (3 keer). O Allah, U bent as-Salam en van U komt vrede. Gezegend bent u, o bezitter van majesteit en eer.", "Direct na de salam.", "De Profeet ﷺ reciteerde dit na elk verplicht gebed."),
        "dua_after_salah_help_dhikr" to DuaText("Help mij u te herinneren", "O Allah, help mij om U te gedenken, U te bedanken en U op de beste manier te aanbidden.", "Na elk gebed adviseerde de Profeet ﷺ Mu'adh (RA) om het te zeggen.", "Een speciale raad van de Profeet ﷺ – uitmuntendheid en standvastigheid in aanbidding."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi voor het slapen gaan", "Glorie zij Allah (33), alle lof is voor Allah (33), Allah is de Grootste (34).", "Voordat hij ging slapen – leerde de Profeet ﷺ het aan Fatimah en Ali (RA).", "De Profeet ﷺ zei dat het beter voor je is dan een dienaar."),
        "dua_sleep_qina_adhab" to DuaText("Bescherming tegen straf", "O Allah, bescherm mij tegen Uw bestraffing op de Dag waarop U Uw dienaren doet herrijzen.", "Drie keer, met de rechterhand onder de wang.", "Verandert de slaap in een herinnering aan de dood en voorbereiding op het Hiernamaals."),
        "dua_bad_dream" to DuaText("Na een nare droom", "Ik zoek mijn toevlucht bij Allah tegen Shaytan, de vervloekte.", "Na een nare droom: drie keer lichtjes naar links droogspugen en dan naar de andere kant draaien.", "De nare droom zal je geen kwaad doen; vertel het aan niemand."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "O Eeuwig Levende, O Onderhouder van allen! Door Uw genade zoek ik hulp.", "Wanneer een zaak heel zwaar wordt.", "Wanneer iets de Profeet ﷺ van streek maakte, zei hij dit."),
        "dua_entering_market" to DuaText("Het betreden van de Marktplaats", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Aan Hem is de heerschappij en aan Hem is de lof. Hij geeft leven en veroorzaakt de dood, en Hij leeft eeuwig en sterft nooit. In Zijn hand is al het goede, en Hij heeft macht over alle dingen.", "Bij het betreden van de marktplaats.", "De hadith vermeldt er een grote beloning voor (een miljoen goede daden)."),
        "dua_adam_forgiveness" to DuaText("Dua van Profeet Adam (AS)", "Onze Heer, we hebben onszelf onrecht aangedaan, en als U ons niet vergeeft en genade met ons heeft, zullen we zeker tot de verliezers behoren.", "Het dua van berouw van Adam en Hawwa (AS).", "Het eerste berouw van de mensheid – Allah accepteerde het."),
        "dua_abu_bakr" to DuaText("Dua leerde Abu Bakr (RA)", "O Allah, ik heb mezelf enorm onrecht aangedaan, en niemand vergeeft zonden behalve U, dus schenk mij vergeving van Uzelf en wees mij genadig. U bent inderdaad de Vergevingsgezinde, de Barmhartige.", "De Profeet ﷺ leerde het aan Abu Bakr as-Siddiq (RA) om in gebed te zeggen (na de tashahhud).", "Een Sunnah dua voor het einde van het gebed."),
        "dua_astaghfirullah_atubu" to DuaText("Dagelijkse Istighfar", "Ik zoek de vergiffenis van Allah en ik wend mij berouwvol tot Hem.", "De Profeet ﷺ vroeg meer dan zeventig keer per dag om vergeving.", "De Profeet ﷺ zei: Ik zoek Allah's vergiffenis en toon meer dan zeventig keer per dag berouw bij Hem."),
        "dua_laylatul_qadr" to DuaText("Dua voor Laylat al-Qadr", "O Allah, U bent het meest vergevingsgezind en U houdt ervan om te vergeven, dus vergeef mij.", "Onderwezen aan Aisha (RA) voor Laylat al-Qadr.", "Een speciale dua voor de laatste nachten van de Ramadan en Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("Koelte van de ogen (echtgenoot en kinderen)", "Onze Heer, schenk ons ​​van onze echtgenoten en onze nakomelingen de koelte van onze ogen, en maak ons ​​leiders van de rechtvaardigen.", "Een Quranische dua voor een rechtschapen echtgenoot en kinderen.", "Voor vrede thuis en rechtvaardige kinderen."),
        "dua_righteous_children" to DuaText("Voor rechtvaardige nakomelingen", "Mijn Heer, schenk mij van Uzelf zuivere nakomelingen. U bent inderdaad de Hoorder van de smeekbeden.", "De dua van Profeet Zakariyya (AS).", "Een korandua voor mensen die op zoek zijn naar kinderen."),
        "dua_ibrahim_prayer_family" to DuaText("Oprichters van het gebed", "Mijn Heer, maak mij een stichter van het gebed, en van mijn nakomelingen. Onze Heer, aanvaard mijn smeekbede. Onze Heer, vergeef mij, mijn ouders en de gelovigen op de Dag waarop de rekening wordt opgesteld.", "De dua van Profeet Ibrahim (AS) voor hemzelf en zijn nakomelingen.", "Vaak gereciteerd aan het einde van het gebed."),
        "dua_newlywed" to DuaText("Felicitatie van de pasgetrouwden", "Moge Allah u zegenen, zegeningen over u zenden en u beiden in goedheid samenbrengen.", "Als je iemand feliciteert met zijn huwelijk.", "De Sunnah-felicitatie voor een huwelijk."),
        "dua_before_eating" to DuaText("Voor het eten", "In de naam van Allah. (Indien vergeten:) In de naam van Allah, aan het begin en aan het einde.", "Voor het eten. Als je het vergeet, zeg het dan halverwege.", "Het zeggen van Bismillah weerhoudt Shaytan ervan het eten te delen."),
        "dua_after_eating" to DuaText("Na het eten", "Alle lof komt toe aan Allah die mij dit heeft gevoed en voor mij heeft voorzien zonder enige macht of macht van mijn kant.", "Na het beëindigen van de maaltijd.", "De zonden uit het verleden van degene die het zegt, zijn vergeven."),
        "dua_host" to DuaText("Voor de gastheer", "O Allah, zegen hen in wat U hen hebt gegeven, vergeef hen en heb medelijden met hen.", "Voor de gastheer, na het eten bij iemand thuis.", "De gastheer bedanken op de Sunnah-manier."),
        "dua_breaking_fast" to DuaText("Bij het verbreken van het vasten", "De dorst is verdwenen, de aderen zijn bevochtigd en de beloning is bevestigd, als Allah het wil.", "Op het moment van iftar.", "De Profeet ﷺ zei dit toen hij zijn vasten verbrak."),
        "dua_new_clothes" to DuaText("Nieuwe kleren dragen", "O Allah, alle lof is aan U; Je hebt mij hiermee bekleed. Ik vraag U om het goede ervan en het goede waarvoor het gemaakt is, en ik zoek toevlucht bij U tegen het kwade ervan en het kwade waarvoor het gemaakt is.", "Bij het dragen van een nieuw kledingstuk (het benoemen ervan, zoals een overhemd of tulband).", "De Profeet ﷺ maakte deze dua toen hij een nieuw kledingstuk droeg. (De dagelijkse dua voor het aankleden staat onder 'Aankleden'.)"),
        "dua_rabbana_atina" to DuaText("Goed in deze wereld en het hiernamaals", "Onze Heer, geef ons het goede in deze wereld en het goede in het Hiernamaals, en bescherm ons tegen de bestraffing van het Vuur.", "De dua die de Profeet ﷺ het vaakst maakte.", "Een dua die al het goede van deze wereld en het Hiernamaals verzamelt."),
        "dua_rabbi_zidni_ilma" to DuaText("Toename van kennis", "Mijn Heer, vermeerder mij in kennis.", "Voor een toename van kennis.", "Allah beval de Profeet ﷺ om te vragen om een ​​toename van niets anders dan kennis."),
        "dua_musa_sharh_sadr" to DuaText("Opening van de kist (Musa AS)", "Mijn Heer, breid mijn borst voor mij uit, verlicht mijn taak voor mij en maak de knoop uit mijn tong los, zodat ze mijn spraak kunnen begrijpen.", "Voor een examen, een toespraak of een moeilijke taak.", "De dua van Profeet Musa (AS) – kalmte van hart en gemak in het werk."),
        "dua_la_tuzigh" to DuaText("Standvastigheid van het hart", "Onze Heer, laat ons hart niet afwijken nadat U ons heeft geleid, en schenk ons ​​genade van Uzelf. U bent inderdaad de Schenker.", "Voor standvastigheid in leiding.", "Een dua om standvastig te blijven in het geloof."),
        "dua_ya_muqallib" to DuaText("O Hartendraaier", "O Hartendrager, houd mijn hart standvastig op Uw religie.", "De Profeet ﷺ maakte deze dua vaak.", "Volgens Umm Salamah (RA) is de dua die de Profeet ﷺ het vaakst maakte."),
        "dua_la_tuakhidhna" to DuaText("Laatste verzen van soera Al-Baqarah", "Onze Heer, reken ons niet aan als we het vergeten of een fout maken. Onze Heer, leg ons geen last op zoals U de mensen vóór ons hebt opgelegd. Onze Heer, belast ons niet met wat we niet kunnen dragen. Vergeef ons, vergeef ons en heb medelijden met ons. U bent onze Beschermer, dus help ons tegen de ongelovige mensen.", "'s Avonds voor het slapengaan – de laatste twee verzen van Surah al-Baqarah.", "Iedereen die 's avonds de laatste twee verzen van Surah al-Baqarah reciteert, zal voor hem voldoende zijn."),
        "dua_visiting_sick" to DuaText("Op bezoek bij de zieken", "Ik vraag Allah de Machtige, Heer van de Machtige Troon, om je te genezen.", "Zeven keer bij ziekenbezoek.", "Als het tijdstip van overlijden nog niet is aangebroken, zal Allah hem genezen."),
        "dua_ruqyah_pain" to DuaText("Voor lichamelijke pijn", "Ik zoek toevlucht bij Allah en Zijn macht tegen het kwaad van wat ik voel en waar ik bang voor ben.", "Plaats je hand waar het pijn doet, zeg drie keer Bismillah, daarna zeven keer deze dua.", "De Profeet ﷺ leerde het aan Uthman ibn Abil-'As (RA) tegen pijn."),
        "dua_ruqyah_nabawi" to DuaText("Profetische Ruqyah voor de zieken", "O Allah, Heer van de mensheid! Verwijder de schade en zorg voor genezing, want Jij bent Degene die geneest; er is geen geneesmiddel behalve Uw geneesmiddel – een geneesmiddel dat geen ziekte achterlaat.", "Terwijl u de hand over de zieke uitstrekt.", "De Profeet ﷺ reciteerde dit toen hij zieke leden van zijn familie bezocht."),
        "dua_kalimat_tammat" to DuaText("Toevlucht zoeken in perfecte woorden", "Ik zoek toevlucht bij de perfecte woorden van Allah tegen het kwaad van wat Hij heeft geschapen.", "Wanneer u ergens stopt, of 's avonds.", "Degene die ergens stopt en dit zegt, niets zal hem kwaad doen totdat hij deze verlaat."),
        "dua_evil_eye" to DuaText("Bescherming voor kinderen (boze oog)", "Ik zoek bescherming voor jullie zowel in de perfecte woorden van Allah tegen elke duivel en elk giftig schepsel, en tegen elk schadelijk oog.", "De Profeet ﷺ reciteerde dit over Hasan en Husain (RA).", "Een Sunnah-dua om kinderen te beschermen tegen het boze oog en kwaad (één kind zegt 'U'īdhuka')."),
        "dua_seeing_afflicted" to DuaText("Iemand zien die in beproeving verkeert", "Alle lof is voor Allah, die mij heeft gespaard van datgene waarmee Hij jou op de proef heeft gesteld, en mij heeft bevoordeeld boven een groot deel van Zijn schepping.", "Bij het zien van iemand die terechtstaat (zeg het rustig tegen jezelf).", "Degene die dat zegt, wordt voor dat proces beschermd."),
        "dua_istikhara" to DuaText("Salat al-Istikhara", "O Allah, ik zoek het goede door Uw kennis, ik zoek het vermogen door Uw kracht, en ik vraag U om Uw grote milddadigheid. Jij hebt macht en ik heb er geen; Jij weet het en ik niet, en Jij bent de Kenner van het ongeziene. O Allah, als naar Uw weten deze kwestie (breng het in gedachten) goed is voor mijn religie, mijn leven en mijn einde, besluit het dan voor mij, maak het gemakkelijk voor mij en zegen mij daarin. En als naar Uw weten deze zaak slecht is voor mijn religie, mijn leven en mijn einde, keer het dan van mij af en keer mij ervan af, en besluit voor mij het goede, waar het ook mag zijn, maak mij er dan tevreden mee.", "Na twee rak'ahs van vrijwillig gebed, om te zoeken naar wat het beste is in een toegestane kwestie.", "De Profeet ﷺ leerde de metgezellen istikhara in alle zaken, zoals hij hen een soera van de Koran leerde."),
    )
}
